import React, { useState, useEffect } from 'react';
import { uploadFile, getFiles, downloadFile } from '../services/api';
import CryptoFlow from '../components/CryptoFlow';
import { Upload, Download, FileText, AlertTriangle, Server, HardDrive } from 'lucide-react';

const Dashboard = () => {
  const [files, setFiles] = useState([]);
  const [uploadStep, setUploadStep] = useState(0); // 0 = Idle
  const [error, setError] = useState(null);
  
  // Toggles (Requirement 3 & 4)
  const [storageMode, setStorageMode] = useState('local'); // local | minio
  const [cryptoMode, setCryptoMode] = useState('hybrid'); // hybrid | rsa

  useEffect(() => {
    fetchFiles();
  }, []);

  const fetchFiles = async () => {
    try {
      const res = await getFiles();
      setFiles(res.data);
    } catch (err) { console.error("Fetch failed"); }
  };

  const handleUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setError(null);
    setUploadStep(1); // Start Animation

    // Simulate Visual Steps (The backend is fast, so we pace the UI for explainability)
    setTimeout(() => setUploadStep(2), 600);
    setTimeout(() => setUploadStep(3), 1200);
    setTimeout(() => setUploadStep(4), 1800);

    try {
      // Actual Backend Call
      await uploadFile(file); 
      setUploadStep(5);
      setTimeout(() => {
        setUploadStep(0);
        fetchFiles();
      }, 1000);
    } catch (err) {
      setUploadStep(0);
      setError("Upload Failed: Network or Server Error");
    }
  };

  const handleDownload = async (id, name) => {
    try {
      // 1. Visual Feedback
      addLog(`Requesting access to file ID: ${id}...`);
      addLog("Retrieving Encrypted Blob from Storage...");
      
      // 2. The API Call (This triggers PQC Decapsulation + AES Decryption on Backend)
      await downloadFile(id, name);
      
      // 3. Success
      addLog("✅ PQC Decapsulation Successful.");
      addLog("✅ AES-GCM Integrity Tag Verified.");
      addLog("⬇️ Download started.");
      
    } catch (err) {
      console.error("Download Error:", err);
      
      // 4. FAILURE VISUALIZATION (This is for your SCI Paper!)
      addLog("❌ DECRYPTION FAILED.");
      addLog("❌ Integrity Check: TAG MISMATCH.");
      
      setError("CRITICAL: The file has been modified by an unauthorized party (Cloud/Network). Download aborted to protect user.");
    }
  };

  return (
    <div className="p-8 space-y-8">
      
      {/* HEADER & TOGGLES */}
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">Secure Gateway</h2>
          <p className="text-gray-400 text-sm">Post-Quantum Cryptography Enabled</p>
        </div>
        
        <div className="flex gap-4">
            {/* Baseline Crypto Toggle (Requirement 4) */}
            <div className="flex flex-col items-end">
            <label className="text-[10px] text-gray-500 uppercase mb-1">Experiment Mode</label>
            <select 
                value={cryptoMode} 
                onChange={(e) => setCryptoMode(e.target.value)}
                className="bg-scifi-panel border border-scifi-border text-xs text-neon-blue p-2 rounded focus:outline-none"
            >
                <option value="hybrid">Hybrid (PQC + AES)</option>
                <option value="rsa">RSA-2048 (Baseline)</option>
            </select>
          </div>

          {/* Storage Toggle (Requirement 3) */}
          <div className="flex flex-col items-end">
            <label className="text-[10px] text-gray-500 uppercase mb-1">Storage Backend</label>
            <button 
                onClick={() => setStorageMode(storageMode === 'local' ? 'minio' : 'local')}
                className="flex items-center gap-2 bg-scifi-panel border border-scifi-border text-xs text-neon-green p-2 rounded hover:bg-white/5"
            >
                {storageMode === 'local' ? <HardDrive size={14} /> : <Server size={14} />}
                {storageMode === 'local' ? 'Local Filesystem' : 'MinIO Cluster'}
            </button>
          </div>
        </div>
      </div>

      {/* ERROR BANNER (Requirement 2) */}
      {error && (
        <div className="bg-red-900/20 border border-red-500 p-4 rounded flex items-center gap-4 text-red-500 animate-pulse">
          <AlertTriangle size={24} />
          <div>
            <p className="font-bold">CRITICAL SECURITY ALERT</p>
            <p className="text-sm">{error}</p>
          </div>
        </div>
      )}

      {/* UPLOAD SECTION */}
      <div className="bg-scifi-panel border border-scifi-border rounded-xl p-6">
        <h3 className="text-white font-bold mb-4 flex items-center gap-2">
          <Upload size={18} className="text-neon-green" /> Secure Upload
        </h3>
        
        {/* The Animation Component */}
        {uploadStep > 0 ? (
          <CryptoFlow currentStep={uploadStep} />
        ) : (
          <div className="border-2 border-dashed border-gray-700 rounded-lg p-10 text-center hover:border-neon-green transition-colors cursor-pointer relative">
            <input type="file" onChange={handleUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
            <div className="text-gray-500">
              <p className="text-lg font-bold text-white mb-2">Drop files here to encrypt</p>
              <p className="text-xs font-mono">PQC-KEM • AES-256 • HKDF</p>
            </div>
          </div>
        )}
      </div>

      {/* FILE LIST */}
      <div className="bg-scifi-panel border border-scifi-border rounded-xl p-6">
        <h3 className="text-white font-bold mb-4 flex items-center gap-2">
          <FileText size={18} className="text-neon-blue" /> Vault Contents
        </h3>
        <table className="w-full text-left border-collapse">
            <thead>
                <tr className="text-xs text-gray-500 border-b border-gray-800">
                    <th className="p-3">Filename</th>
                    <th className="p-3">Size (Encrypted)</th>
                    <th className="p-3">Upload Date</th>
                    <th className="p-3">Status</th>
                    <th className="p-3 text-right">Action</th>
                </tr>
            </thead>
            <tbody>
                {files.map(file => (
                    <tr key={file.id} className="border-b border-gray-800/50 hover:bg-white/5 transition">
                        <td className="p-3 text-sm text-white font-mono">{file.filename}</td>
                        <td className="p-3 text-sm text-gray-400">{(file.size/1024).toFixed(2)} KB</td>
                        <td className="p-3 text-sm text-gray-400">{new Date(file.date).toLocaleDateString()}</td>
                        <td className="p-3">
                            <span className="bg-neon-green/10 text-neon-green text-[10px] px-2 py-1 rounded border border-neon-green/30">
                                SEALED
                            </span>
                        </td>
                        <td className="p-3 text-right">
                            <button 
                                onClick={() => handleDownload(file.id, file.filename)}
                                className="text-neon-blue hover:text-white transition"
                                title="Decrypt & Download"
                            >
                                <Download size={18} />
                            </button>
                        </td>
                    </tr>
                ))}
            </tbody>
        </table>
      </div>
    </div>
  );
};

export default Dashboard;
